-- The disclosure record. Generated by drizzle-kit, then extended by hand with
-- the two things it cannot express: FORCE ROW LEVEL SECURITY, and a grant that
-- withholds UPDATE and DELETE.
--
-- docs/13-threat-model.md (*Egress*, rule 3) says a customer can ask what left,
-- to which provider, for which project, and that an answer requiring somebody
-- to read code is not good enough. Phase 1d opened the first outbound socket in
-- this repository; this is the table that says what went through it.
--
-- No column here can hold prose. input_chars and input_items measure what left;
-- nothing stores it. A log that quoted the text it discloses would put customer
-- documents in the one table designed to be handed to whoever asks.
--
-- The grant is SELECT and INSERT. standfast_app writes the record and cannot revise
-- it -- the same append-only shape as atom_events, and here the reason is
-- sharper: a process that can edit the log of what it sent has not disclosed
-- anything.
CREATE TYPE "public"."egress_purpose" AS ENUM('extraction', 'embedding', 'judge', 'reranking');--> statement-breakpoint
CREATE TABLE "egress_events" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"org_id" uuid NOT NULL,
	"project_id" uuid NOT NULL,
	"section_id" uuid,
	"purpose" "egress_purpose" NOT NULL,
	"destination" text NOT NULL,
	"model" text NOT NULL,
	"input_items" integer NOT NULL,
	"input_chars" integer NOT NULL,
	"at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "egress_events_input_items_nonneg" CHECK (input_items >= 0),
	CONSTRAINT "egress_events_input_chars_nonneg" CHECK (input_chars >= 0),
	CONSTRAINT "egress_events_destination_not_blank" CHECK (length(btrim(destination)) > 0),
	CONSTRAINT "egress_events_model_not_blank" CHECK (length(btrim(model)) > 0)
);
--> statement-breakpoint
ALTER TABLE "egress_events" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "egress_events" ADD CONSTRAINT "egress_events_org_id_orgs_id_fk" FOREIGN KEY ("org_id") REFERENCES "public"."orgs"("id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "egress_events" ADD CONSTRAINT "egress_events_project_id_projects_id_fk" FOREIGN KEY ("project_id") REFERENCES "public"."projects"("id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "egress_events" ADD CONSTRAINT "egress_events_section_id_document_sections_id_fk" FOREIGN KEY ("section_id") REFERENCES "public"."document_sections"("id") ON DELETE set null ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "egress_events_project_at_idx" ON "egress_events" USING btree ("project_id","at");--> statement-breakpoint
CREATE POLICY "egress_events_org_isolation" ON "egress_events" AS PERMISSIVE FOR ALL TO "standfast_app" USING (org_id = nullif(current_setting('standfast.org_id', true), '')::uuid) WITH CHECK (org_id = nullif(current_setting('standfast.org_id', true), '')::uuid);--> statement-breakpoint
-- ─── Hand-written: what drizzle-kit cannot express ───────────────────────────
--
-- FORCE, so the table owner is bound by the policy too. Without it, whichever
-- role owns the schema reads every org's disclosure log by default.
ALTER TABLE "egress_events" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
GRANT SELECT, INSERT ON "egress_events" TO "standfast_app";
